void releaseProxy(uno_Interface * pUnoI)
{
    if (! --static_cast< UnoInterfaceProxy * >( pUnoI )->nRef )
    {
        // revoke from uno env on last release
        (*static_cast< UnoInterfaceProxy * >( pUnoI )->pBridge->getUnoEnv()->
         revokeInterface)(
             static_cast< UnoInterfaceProxy * >( pUnoI )->pBridge->getUnoEnv(),
             pUnoI );
    }
}
